config.command:
set -euo pipefail
cd {{ execution_path }}
python3 .git/todo-batch/bin/scripts/todo-batch/gates.py --state .git/todo-batch --baseline --backend-dir {{ backend_dir }} --frontend-dir {{ frontend_dir }} --backend-cmd {{ gate_backend }} --frontend-cmd {{ gate_frontend }} --common-cmd {{ gate_common }} --logs {{ workspace_logs }}

set -euo pipefail
cd {{ execution_path }}
printf '%s' {{ block.umsetzen.output }} > .git/todo-batch/umsetzen.txt
python3 .git/todo-batch/bin/scripts/todo-batch/verify.py --state .git/todo-batch --forbidden {{ forbidden_paths }} --max-lines {{ max_lines_per_todo }} --backend-dir {{ backend_dir }} --frontend-dir {{ frontend_dir }} --backend-cmd {{ gate_backend }} --frontend-cmd {{ gate_frontend }} --common-cmd {{ gate_common }} --logs {{ workspace_logs }}

set -euo pipefail
cd {{ execution_path }}
printf '%s' {{ block.review.output }} > .git/todo-batch/review.txt
python3 .git/todo-batch/bin/scripts/todo-batch/verify.py --state .git/todo-batch --after-review --backend-dir {{ backend_dir }} --frontend-dir {{ frontend_dir }} --backend-cmd {{ gate_backend }} --frontend-cmd {{ gate_frontend }} --common-cmd {{ gate_common }} --logs {{ workspace_logs }}

set -euo pipefail
cd {{ execution_path }}
python3 .git/todo-batch/bin/scripts/todo-batch/handover.py --state .git/todo-batch --answer {{ approval_answer }} --on-timeout {{ on_timeout }} --project-path {{ project_path }} --target-branch {{ target_branch }} --run {{ workflow_run_id }} --cleanup {{ backend_dir }}/target {{ frontend_dir }}/node_modules node_modules
